function rand(a,b){return a+Math.random()*(b-a);}

class Bird{
  constructor(i){
    this.i=i;
    this.speed = rand(0.00025,0.00045);
    this.t = Math.random();
    this.phase = Math.random()*Math.PI*2;
    this.size = rand(10,22);
    this.lateral = rand(-40,40);
    this.trail=[];
    this.color = PALETTE[i%PALETTE.length];
  }
  update(dt){
    this.t += this.speed*dt;
    if(this.t>1) this.t-=1;
  }
  pos(){
    const w=W(), h=H();
    const p0={x:-0.15*w, y:1.15*h};
    const p1={x:0.15*w, y:0.55*h + this.lateral};
    const p2={x:0.85*w, y:0.45*h - this.lateral};
    const p3={x:1.15*w, y:-0.15*h};
    const t=this.t;
    const mt=1-t;
    const x = mt*mt*mt*p0.x + 3*mt*mt*t*p1.x + 3*mt*t*t*p2.x + t*t*t*p3.x;
    const y = mt*mt*mt*p0.y + 3*mt*mt*t*p1.y + 3*mt*t*t*p2.y + t*t*t*p3.y;
    const osc = Math.sin(this.t*Math.PI*6 + this.phase)*6;
    return {x, y:y+osc};
  }
}

const NUM_BIRDS = 14;
const NUM_DUST = 40;

let birds=[];
for(let i=0;i<NUM_BIRDS;i++) birds.push(new Bird(i));

let dust=[];
for(let i=0;i<NUM_DUST;i++){
  dust.push({
    x:Math.random(), y:Math.random(),
    r: rand(1,3.2),
    speed: rand(0.00002,0.00006),
    drift: rand(-0.00003,0.00003),
    color: PALETTE[Math.floor(Math.random()*PALETTE.length)],
    alpha: rand(0.15,0.5)
  });
}

let last=performance.now();

function centerFade(x,y){
  const w=W(), h=H();
  const cx=w/2, cy=h/2;
  const dx=x-cx, dy=y-cy;
  const dist=Math.sqrt(dx*dx+dy*dy);
  const radius=Math.min(w,h)*0.24;
  if(dist<radius){
    return 0.12 + 0.88*(dist/radius);
  }
  return 1;
}

function drawBirdShape(x,y,size,angle,color,alpha){
  ctx.save();
  ctx.translate(x,y);
  ctx.rotate(angle);
  ctx.globalAlpha = alpha;
  ctx.beginPath();
  ctx.moveTo(0,-size*0.5);
  ctx.lineTo(size*0.9, size*0.15);
  ctx.lineTo(0, size*0.05);
  ctx.lineTo(-size*0.9, size*0.15);
  ctx.closePath();
  const grad = ctx.createLinearGradient(-size,0,size,0);
  grad.addColorStop(0, color);
  grad.addColorStop(1, 'rgba(255,255,255,0.6)');
  ctx.fillStyle = grad;
  ctx.shadowColor = color;
  ctx.shadowBlur = size*0.8;
  ctx.fill();
  ctx.restore();
}

function loop(now){
  const dt = now-last; last=now;
  const w=W(), h=H();

  ctx.clearRect(0,0,w,h);

  ctx.save();
  const g1 = ctx.createRadialGradient(w*0.05,h*0.9,0, w*0.05,h*0.9, w*0.5);
  g1.addColorStop(0, PALETTE[1]+'33');
  g1.addColorStop(1, 'transparent');
  ctx.fillStyle=g1;
  ctx.fillRect(0,0,w,h);
  const g2 = ctx.createRadialGradient(w*0.95,h*0.08,0, w*0.95,h*0.08, w*0.5);
  g2.addColorStop(0, PALETTE[2]+'22');
  g2.addColorStop(1,'transparent');
  ctx.fillStyle=g2;
  ctx.fillRect(0,0,w,h);
  ctx.restore();

  for(const d of dust){
    d.x += d.drift;
    d.y -= d.speed;
    if(d.y<-0.05) d.y=1.05;
    if(d.x<-0.05) d.x=1.05;
    if(d.x>1.05) d.x=-0.05;
    const px=d.x*w, py=d.y*h;
    const fade = centerFade(px,py);
    ctx.beginPath();
    ctx.globalAlpha = d.alpha*fade;
    ctx.fillStyle = d.color;
    ctx.arc(px,py,d.r,0,Math.PI*2);
    ctx.fill();
  }
  ctx.globalAlpha=1;

  for(const b of birds){
    b.update(dt);
    const p = b.pos();
    b.trail.push({x:p.x,y:p.y});
    if(b.trail.length>16) b.trail.shift();

    ctx.save();
    for(let k=1;k<b.trail.length;k++){
      const a = b.trail[k-1], c = b.trail[k];
      const alpha = (k/b.trail.length)*0.35*centerFade(c.x,c.y);
      ctx.beginPath();
      ctx.moveTo(a.x,a.y);
      ctx.lineTo(c.x,c.y);
      ctx.strokeStyle = b.color;
      ctx.globalAlpha = alpha;
      ctx.lineWidth = 1.4;
      ctx.stroke();
    }
    ctx.restore();

    const prev = b.trail.length>1 ? b.trail[b.trail.length-2] : p;
    const angle = Math.atan2(p.y-prev.y, p.x-prev.x);
    const fade = centerFade(p.x,p.y);
    drawBirdShape(p.x,p.y,b.size, angle, b.color, 0.8*fade);
  }
  ctx.globalAlpha=1;

  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
